head.b:skin:
    :root{--bg:#071426;--panel:#0e2038;--panel2:#132945;--blue:#1685ff;--blue2:#4ca2ff;--text:#f4f8ff;--muted:#9fb2cc;--line:#203955;--danger:#ff667a;--radius:18px}
    *{box-sizing:border-box}
    html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
    body{padding-bottom:78px}
    a{color:inherit;text-decoration:none}
    button,input,textarea{font:inherit}
    button{cursor:pointer}
    .blogger-shell{display:none}
    .boot-screen{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:24px;text-align:center;color:var(--muted)}
    .boot-spinner{width:34px;height:34px;border:3px solid #203955;border-top-color:var(--blue2);border-radius:50%;animation:dotspin .8s linear infinite}
    @keyframes dotspin{to{transform:rotate(360deg)}}
    .app{max-width:760px;margin:0 auto;min-height:100vh;background:var(--bg);position:relative}
    .topbar{height:66px;display:flex;align-items:center;gap:12px;padding:0 17px;border-bottom:1px solid var(--line);position:sticky;top:0;background:rgba(7,20,38,.96);backdrop-filter:blur(14px);z-index:20}
    .brandmark{width:40px;height:40px;border-radius:13px;background:linear-gradient(135deg,#39a0ff,#0759df);display:grid;place-items:center;font-size:24px;font-weight:900;box-shadow:0 5px 20px #1685ff35}
    .brand{font-size:22px;font-weight:850;letter-spacing:-.7px}.brand span{color:var(--blue2)}
    .top-spacer{flex:1}
    .icon-btn{border:1px solid var(--line);background:var(--panel);color:var(--text);width:42px;height:42px;border-radius:14px;display:grid;place-items:center;font-size:19px;position:relative}.notify-badge{position:absolute;right:-4px;top:-5px;min-width:18px;height:18px;padding:0 4px;border-radius:99px;background:#ff4567;color:#fff;font-size:10px;font-weight:800;display:grid;place-items:center;border:2px solid var(--bg)}.notification-row{display:flex;align-items:flex-start;gap:11px;padding:13px 2px;border-bottom:1px solid var(--line);cursor:pointer}.notification-row:last-child{border-bottom:0}.notification-row.unread{background:#1685ff12}.notification-row .avatar{width:42px;height:42px;font-size:15px}.notification-copy{flex:1;min-width:0;font-size:13px;line-height:1.4}.notification-time{font-size:10px;color:var(--muted);margin-top:5px}.notification-dot{width:8px;height:8px;border-radius:50%;background:#1685ff;flex-shrink:0;margin-top:6px}.notification-actions{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 14px}
    .content{padding:17px 15px 22px}
    .eyebrow{font-size:11px;letter-spacing:1.5px;color:var(--blue2);font-weight:800;text-transform:uppercase}
    h1,h2,h3,p{margin-top:0}
    h1{font-size:27px;letter-spacing:-.7px;margin:7px 0}
    h2{font-size:19px;margin-bottom:12px}
    .muted{color:var(--muted)}.small{font-size:12px}.hidden{display:none!important}
    .card{background:linear-gradient(145deg,var(--panel),#0a1a2f);border:1px solid var(--line);border-radius:var(--radius);padding:16px;margin-bottom:13px}
    .primary{background:linear-gradient(135deg,#1685ff,#0862dc);border:0;color:white;border-radius:13px;padding:13px 16px;font-weight:750;min-height:46px}
    .secondary{background:var(--panel2);border:1px solid var(--line);color:var(--text);border-radius:13px;padding:12px 14px;min-height:44px}
    .full{width:100%}
    .field{width:100%;background:#08182b;border:1px solid #29425f;color:white;border-radius:13px;padding:14px;margin:6px 0 12px;outline:none}
    .field:focus{border-color:var(--blue);box-shadow:0 0 0 3px #1685ff20}
    label{font-size:12px;color:var(--muted);display:block}
    .auth-wrap{max-width:440px;margin:6vh auto;padding:20px}
    .auth-logo{text-align:center;margin-bottom:24px}.auth-logo .brandmark{width:70px;height:70px;font-size:39px;border-radius:22px;margin:0 auto 12px}
    .auth-logo h1{font-size:32px}.auth-logo p{color:var(--muted);font-size:14px}
    .auth-switch{text-align:center;margin-top:16px;font-size:13px;color:var(--muted)}
    .link-button{background:none;border:0;color:var(--blue2);font-weight:750;padding:6px}
    .notice{font-size:12px;line-height:1.5;color:var(--muted);margin-top:13px}
    .status{font-size:12px;margin:10px 0;color:#ffd479;min-height:18px;overflow-wrap:anywhere}
    .section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:4px 0 14px}
    .section-head h1{margin:0}
    .search{width:100%;background:var(--panel);border:1px solid var(--line);border-radius:14px;color:white;padding:13px 15px;margin-bottom:15px}
    .row{display:flex;align-items:center;gap:12px;min-width:0}
    .avatar{width:48px;height:48px;border-radius:50%;background:linear-gradient(135deg,#1d4169,#1685ff);display:grid;place-items:center;flex-shrink:0;font-size:18px;font-weight:800;overflow:hidden}
    .avatar img{width:100%;height:100%;object-fit:cover}
    .grow{flex:1;min-width:0}.truncate{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
    .chat-row{display:flex;align-items:center;gap:12px;padding:13px 4px;border-bottom:1px solid #203955;cursor:pointer}
    .chat-row:last-child{border-bottom:0}.chat-name{font-size:15px;font-weight:750;margin-bottom:5px}.chat-preview{font-size:12px;color:var(--muted)}
    .pill{font-size:10px;background:#123e6c;color:#9ed0ff;padding:5px 8px;border-radius:999px}
    .empty{text-align:center;padding:42px 16px;color:var(--muted)}.empty .big{font-size:42px;margin-bottom:12px}
    .bottom-nav{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:100%;max-width:760px;height:70px;padding:7px 9px calc(7px + env(safe-area-inset-bottom));display:flex;justify-content:space-around;align-items:center;background:rgba(8,24,43,.97);border-top:1px solid var(--line);backdrop-filter:blur(16px);z-index:30}
    .nav-btn{background:none;border:0;color:#7891af;display:flex;flex-direction:column;align-items:center;gap:4px;font-size:10px;min-width:54px;padding:5px}
    .nav-btn b{font-size:21px;font-weight:500;line-height:22px}.nav-btn.active{color:#67b0ff}
    .fab{position:fixed;right:max(20px,calc((100vw - 720px)/2));bottom:88px;width:55px;height:55px;border:0;border-radius:18px;background:linear-gradient(135deg,#1685ff,#0759df);color:white;font-size:26px;box-shadow:0 10px 28px #1685ff40;z-index:10}
    .chat-header{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);position:sticky;top:66px;background:var(--bg);z-index:10}
    .back-btn{border:0;background:none;color:white;font-size:25px;padding:4px 7px}
    .messages{display:flex;flex-direction:column-reverse;gap:9px;padding:14px 13px;overflow-y:auto;min-height:45vh;max-height:calc(100vh - 235px)}
    .bubble{max-width:82%;padding:11px 13px;border-radius:16px;background:var(--panel2);align-self:flex-start;overflow-wrap:anywhere;white-space:pre-wrap;line-height:1.4;font-size:14px}
    .bubble.mine{align-self:flex-end;background:linear-gradient(135deg,#167df1,#0758c8);border-bottom-right-radius:5px}
    .bubble:not(.mine){border-bottom-left-radius:5px}.bubble-time{font-size:10px;opacity:.7;text-align:right;margin-top:5px}
    .composer{position:sticky;bottom:70px;display:flex;gap:8px;padding:10px 12px;background:var(--bg);border-top:1px solid var(--line)}
    .composer input{flex:1;min-width:0;background:var(--panel);border:1px solid var(--line);border-radius:22px;padding:12px 15px;color:white;outline:none}
    .send-btn{width:46px;border:0;border-radius:16px;background:var(--blue);color:white;font-size:20px}
    .story-strip{display:flex;gap:14px;overflow:auto;padding:6px 0 18px}
    .story{text-align:center;min-width:62px;font-size:11px;color:var(--muted)}
    .story-ring{width:57px;height:57px;padding:3px;border:2px solid var(--blue);border-radius:50%;margin:0 auto 6px}
    .story-ring .avatar{width:100%;height:100%;font-size:18px}
    .feed-post{background:var(--panel);border:1px solid var(--line);border-radius:18px;margin:12px 0;overflow:hidden}
    .post-image{display:block;width:100%;max-height:520px;object-fit:cover;background:#08182b}
    .post-text{padding:14px;font-size:14px;line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere}
    .post-meta{display:flex;align-items:center;gap:10px;padding:13px}
    .post-meta .avatar{width:42px;height:42px;font-size:15px}
    .post-time{font-size:11px;color:var(--muted);margin-top:3px}
    .post-composer-preview{width:100%;max-height:280px;object-fit:contain;border-radius:12px;background:#08182b;margin:8px 0}
    .post-actions{display:flex;align-items:center;gap:18px;padding:0 13px 13px;color:var(--muted)}
    .post-actions button{border:0;background:none;color:var(--muted);padding:6px 0;font-weight:700}
    .post-actions button:disabled{opacity:.5}
    .like-btn{display:inline-flex;align-items:center;gap:6px;border-radius:9px;padding:8px 10px!important}.like-btn.liked{color:#ff5470!important}.like-btn .heart{font-size:17px;line-height:1}
    .post-head{display:flex;align-items:center;gap:10px;padding:13px}
    .post-art{min-height:180px;display:grid;place-items:center;background:radial-gradient(circle at 25% 20%,#1a65a3,#0a1b33 60%,#111b38);font-size:54px}
    .post-copy{padding:13px;font-size:14px}.post-actions{display:flex;gap:18px;padding:0 13px 13px;color:var(--muted)}
    .profile-hero{text-align:center;padding:25px 16px}.profile-hero .avatar{width:82px;height:82px;margin:0 auto 12px;font-size:28px}.profile-photo-actions{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:10px 0 16px}.profile-photo-actions input{display:none}
    .profile-stats{display:flex;justify-content:space-around;padding:15px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
    .profile-stats strong{display:block;font-size:18px}.public-profile-actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:14px 0}.public-profile-actions button{min-width:120px}.profile-stats span{font-size:11px;color:var(--muted)}
    .stat-btn{background:none;border:0;color:inherit;cursor:pointer;min-width:75px;padding:8px;border-radius:10px}.stat-btn:active{background:#1685ff20}.stat-btn span{display:block}.follow-list-row{display:flex;align-items:center;gap:10px;padding:11px 0;border-bottom:1px solid var(--line);min-width:0}.follow-list-row:last-child{border-bottom:0}.follow-list-row .grow{cursor:pointer}.follow-list-row .avatar{width:44px;height:44px}.follow-list-actions{display:flex;align-items:center;gap:5px;flex-shrink:0}.follow-list-actions button{font-size:11px;min-height:34px;padding:7px 9px;border-radius:10px}.follow-btn{min-width:94px;padding:10px 12px}.follow-btn.following{background:var(--panel2);border:1px solid var(--line)}
    .people-result{width:100%;min-width:0}.people-result-main{display:flex;align-items:center;gap:12px;min-width:0}.people-result-main .grow{overflow:hidden}.people-result-name,.people-result-handle,.people-result-bio{display:block;overflow-wrap:anywhere;word-break:normal}.people-result-bio{margin-top:4px}.people-result-actions{display:flex;gap:5px;flex-wrap:nowrap;margin:12px 0 0 0;width:100%;min-width:0}.people-result-actions button{flex:1 1 0;min-width:0;padding:8px 3px;font-size:11px;line-height:1.2;white-space:nowrap;letter-spacing:-.15px}
    @media(max-width:380px){.people-result-actions{gap:4px}.people-result-actions button{flex:1 1 0;padding:8px 2px;font-size:10px;white-space:nowrap}}
    .reel-placeholder{min-height:55vh;border-radius:20px;display:grid;place-items:center;text-align:center;padding:25px;background:linear-gradient(160deg,#173b65,#081529 55%,#101c3b)}
    .reel-placeholder .play{font-size:56px;color:#75b9ff}
    .footer-note{text-align:center;color:#617b9c;font-size:10px;padding:16px}
    @media(min-width:700px){.content{padding:22px}.auth-wrap{margin-top:8vh}.messages{max-height:calc(100vh - 250px)}}

    /* dot.tag white + electric-blue glow redesign */
    :root{--bg:#f7fbff;--panel:#ffffff;--panel2:#f0f7ff;--blue:#1677ff;--blue2:#38a0ff;--text:#14243b;--muted:#70839c;--line:#dce9f8;--danger:#e74768;--radius:22px}
    html,body{background:radial-gradient(ellipse at 50% -10%,#e1f1ff 0%,#f7fbff 42%,#f8fbff 100%);color:var(--text)}
    body{padding-bottom:calc(84px + env(safe-area-inset-bottom))}
    .app{background:transparent;box-shadow:0 0 70px #318bff0b}
    .topbar{height:72px;padding:0 18px;background:rgba(255,255,255,.88);border-bottom:1px solid #dceaff;box-shadow:0 8px 28px #287cff0c;backdrop-filter:blur(22px)}
    .brandmark{background:linear-gradient(145deg,#61c2ff 0%,#2388ff 48%,#0754e8 100%);box-shadow:0 0 0 5px #2b8cff12,0 8px 25px #1677ff40,inset 0 1px 0 #ffffffa8;color:white}
    .brand{color:#122541;letter-spacing:-1px}.brand span{color:#1677ff;text-shadow:0 0 16px #258aff66}
    .icon-btn{background:#fff;color:#2b5b96;border:1px solid #d6e7fb;box-shadow:0 4px 16px #1c78ff0c;transition:transform .18s,box-shadow .18s}.icon-btn:active{transform:scale(.96);box-shadow:0 0 0 4px #1685ff18}
    .notify-badge{border-color:#fff}
    .content{padding:20px 15px 28px}
    .eyebrow{color:#1476f8;letter-spacing:1.8px}
    h1{color:#122541;letter-spacing:-1px}h2,h3{color:#192e49}
    .muted,.small{color:var(--muted)}
    .card{background:linear-gradient(150deg,#fff 0%,#fbfdff 100%);border:1px solid #dfebfa;border-radius:23px;padding:17px;box-shadow:0 8px 28px #1c6ed00a,0 1px 2px #1c6ed00a}
    .primary{background:linear-gradient(110deg,#3eabff 0%,#1677ff 52%,#1559e8 100%);box-shadow:0 7px 20px #1677ff35,inset 0 1px 0 #ffffff66;border-radius:15px;transition:transform .18s,box-shadow .18s}.primary:active{transform:translateY(1px);box-shadow:0 3px 10px #1677ff30}
    .secondary{background:linear-gradient(180deg,#fff,#f2f8ff);border:1px solid #cfe2fb;color:#24568e;box-shadow:0 4px 12px #1677ff08}
    .field,.search{background:#fff;color:#182c47;border:1px solid #d5e5f8;border-radius:15px;box-shadow:inset 0 1px 3px #24558a08;transition:border-color .2s,box-shadow .2s}
    .field::placeholder,.search::placeholder,.composer input::placeholder{color:#91a4bc}
    .field:focus,.search:focus{border-color:#55a5ff;box-shadow:0 0 0 4px #1685ff15,0 0 18px #1685ff10}
    label{color:#6b819c}
    .auth-wrap{margin:5vh auto;padding:22px}.auth-logo .brandmark{box-shadow:0 0 0 8px #2388ff0d,0 12px 35px #1677ff3d}.auth-logo h1{font-size:35px}.auth-logo p{color:#7286a0}
    .link-button{color:#0875fa}.status{color:#a86a08}
    .section-head{margin:7px 0 17px}
    /* Restore the original Blue-White glass welcome panel */
    .welcome-card{margin:4px 0 25px;padding:24px 22px;border:1px solid rgba(255,255,255,.88);border-radius:32px;background:linear-gradient(125deg,rgba(225,240,255,.78),rgba(239,237,255,.72) 55%,rgba(220,245,255,.76));box-shadow:inset 0 1px 0 rgba(255,255,255,.9),0 12px 28px rgba(48,113,215,.08);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}
    .welcome-card .section-head{margin:0;align-items:center}
    .welcome-card h1{font-size:clamp(23px,5vw,34px);line-height:1.18;color:#142b49}
    .welcome-card .muted{color:#7186a2}
    .welcome-card .eyebrow{font-size:12px;letter-spacing:2px}
    .welcome-card .pill{background:rgba(255,255,255,.55);border:1px solid rgba(255,255,255,.7);color:#3869c5;padding:8px 12px;font-size:12px}
    @media(max-width:480px){.welcome-card{padding:20px 16px;border-radius:27px}.welcome-card .section-head{gap:8px}.welcome-card h1{font-size:25px}}
    .avatar{background:linear-gradient(140deg,#9bd9ff,#2688ff 65%,#1555e8);color:#fff;box-shadow:0 4px 14px #1677ff20}
    .chat-row{border-bottom:1px solid #e7eff9;padding:14px 5px}.chat-row:active,.follow-list-row:active{background:#edf6ff;border-radius:14px}.chat-name{color:#192e49}.chat-preview{color:#7b8da5}
    .pill{background:#e8f3ff;color:#1673e9;border:1px solid #d6e9ff}
    .empty{color:#8193aa}.empty .big{filter:drop-shadow(0 5px 12px #1677ff20)}
    .bottom-nav{height:calc(76px + env(safe-area-inset-bottom));padding:9px 10px calc(10px + env(safe-area-inset-bottom));background:rgba(255,255,255,.92);border-top:1px solid #dce9f8;box-shadow:0 -8px 30px #256fbd0d;backdrop-filter:blur(22px)}
    .nav-btn{color:#8798ae;min-width:54px;border-radius:14px;transition:color .18s,background .18s}.nav-btn b{font-size:22px}.nav-btn.active{color:#1677ff;text-shadow:0 0 15px #1685ff35}.nav-btn.active b{filter:drop-shadow(0 0 6px #1685ff45)}
    .fab{background:linear-gradient(135deg,#4ab5ff,#1677ff 60%,#124fe0);box-shadow:0 0 0 6px #1685ff12,0 12px 32px #1677ff4d,0 0 25px #1685ff20;border-radius:20px}
    .chat-header{background:rgba(255,255,255,.95);border-bottom:1px solid #e0ebf8;box-shadow:0 5px 16px #1677ff08}.back-btn{color:#2864a8}
    .messages{background:linear-gradient(180deg,#f8fbff,#f1f7ff)}
    /* Chat layout fix: keep the header in normal flow so it cannot cover messages. */
    #chatRoomView{display:flex;flex-direction:column;min-height:calc(100dvh - env(safe-area-inset-top));}
    #chatRoomView .chat-header{position:relative;top:auto;flex:0 0 auto;z-index:2;}
    #chatRoomView .messages{flex:1 1 auto;min-height:0;height:calc(100dvh - 245px);max-height:none;overflow-y:auto;overscroll-behavior:contain;}
    #chatRoomView .composer{position:sticky;bottom:0;flex:0 0 auto;z-index:3;}
    @supports not (height: 100dvh){#chatRoomView{min-height:100vh}#chatRoomView .messages{height:calc(100vh - 245px)}}
    .bubble{background:#fff;color:#1a2e48;border:1px solid #dfebf8;box-shadow:0 3px 10px #1d5c9b08;border-radius:18px}.bubble.mine{background:linear-gradient(135deg,#41aaff,#1677ff 68%,#165de8);color:white;border:0;box-shadow:0 5px 15px #1677ff22;border-bottom-right-radius:5px}
    .composer{background:rgba(255,255,255,.97);border-top:1px solid #dce9f8}.composer input{background:#f8fbff;border:1px solid #d7e6f8;color:#172b45}.send-btn{background:linear-gradient(135deg,#39a9ff,#1677ff);box-shadow:0 5px 14px #1677ff30}
    .story-strip{padding:8px 0 20px}.story{color:#7186a0}.story-ring{border:2px solid #2589ff;box-shadow:0 0 0 3px #1685ff0e,0 0 15px #1685ff15}
    .feed-post{background:#fff;border:1px solid #e0ebf8;border-radius:23px;box-shadow:0 9px 28px #1d5b990c;margin:15px 0;overflow:hidden;transition:box-shadow .2s}.feed-post:active{box-shadow:0 10px 30px #1677ff12}
    .post-image{background:#eef6ff}.post-text{color:#263c57}.post-meta,.post-head{padding:15px}.post-time{color:#91a1b5}.post-composer-preview{background:#f1f7ff}
    .post-actions{color:#70839c;padding:0 15px 15px}.post-actions button{color:#607994}.like-btn.liked{color:#f04472!important;text-shadow:0 0 12px #ff3d751e}.like-btn .heart{transition:transform .2s}.like-btn.liked .heart{filter:drop-shadow(0 0 5px #ff4c7b40);transform:scale(1.08)}
    .post-art{background:radial-gradient(circle at 25% 20%,#a5dcff,#eaf5ff 58%,#d5e8ff);color:#1677ff;text-shadow:0 5px 22px #1677ff25}
    .profile-hero{background:linear-gradient(180deg,#eef7ff 0%,#fff 72%);border-radius:23px 23px 0 0}.profile-hero .avatar{box-shadow:0 0 0 5px #fff,0 0 0 8px #d9edff,0 10px 24px #1677ff20}
    .profile-stats{border-color:#e0ebf8}.profile-stats span{color:#7a8ca3}.stat-btn:active{background:#eaf4ff}.follow-list-row{border-bottom-color:#e4eef9}.follow-btn.following{background:#edf6ff;border:1px solid #cfe4ff;color:#216ac0}
    .people-result-actions button{border-radius:12px}.reel-placeholder{background:radial-gradient(circle at 50% 25%,#e1f3ff,#f7fbff 60%,#eaf4ff);border:1px solid #dcecff;color:#234a79}.reel-placeholder .play{color:#1685ff;filter:drop-shadow(0 0 15px #1685ff55)}
    .footer-note{color:#9aabc0}
    .notification-row{border-bottom-color:#e3edf8}.notification-row.unread{background:#edf6ff}.notification-dot{background:#1677ff}
    .boot-screen{color:#7b8fa8}.boot-spinner{border-color:#d9e9fb;border-top-color:#1677ff}
    ::selection{background:#bfe0ff;color:#0e3f83}
    @media(min-width:700px){.app{border-left:1px solid #e4eef9;border-right:1px solid #e4eef9;background:#ffffff8c}.content{padding:24px}.feed-post{border-radius:25px}}

      /* dot.tag Premium Blue redesign — visual layer only; Firebase logic unchanged */
    :root{--bg:#f4f8ff;--panel:#ffffff;--panel2:#edf4ff;--blue:#176bff;--blue2:#38a0ff;--text:#102344;--muted:#687c9b;--line:#dce8fb;--danger:#e54865;--radius:22px}
    html,body{background:radial-gradient(ellipse at 50% -12%,#dceaff 0%,#f4f8ff 45%,#f8fbff 100%)!important;color:var(--text)!important}
    .app{background:transparent!important}
    .topbar{background:rgba(255,255,255,.88)!important;border-bottom:1px solid #dbe8ff!important;box-shadow:0 8px 30px rgba(25,104,255,.07);backdrop-filter:blur(20px)}
    .brandmark{background:linear-gradient(135deg,#56b7ff 0%,#247cff 48%,#174de8 100%)!important;box-shadow:0 0 0 4px #e5efff,0 8px 28px #287bff55!important}
    .dot-logo-svg{width:76%;height:76%;display:block;filter:drop-shadow(0 1px 2px #0649b866)}
    .auth-logo .dot-logo-svg{width:76%;height:76%}
    .brand span{color:#176bff!important;text-shadow:0 0 18px #3d8bff45}
    .icon-btn{background:#fff!important;color:#1756b8!important;border-color:#d7e5ff!important;box-shadow:0 5px 16px #287bff12}
    .icon-btn:active,button:active{transform:translateY(1px)}
    .content{color:var(--text)}
    .panel,.card,.post-card,.profile-card,.chat-card,.form-card,.section-card,.modal-card,.auth-card,.composer,.notification-card,.list-card{background:rgba(255,255,255,.94)!important;border:1px solid #e0eaff!important;border-radius:22px!important;box-shadow:0 12px 34px rgba(28,91,190,.075),0 2px 8px rgba(26,100,255,.04)!important}
    input,textarea,select{background:#f7faff!important;color:#132a4d!important;border:1px solid #d6e4fb!important;border-radius:14px!important;outline:none}
    input:focus,textarea:focus,select:focus{border-color:#4593ff!important;box-shadow:0 0 0 4px #3184ff20,0 0 18px #3184ff15!important}
    button,.primary-btn,.btn-primary,.submit-btn,.follow-btn,.send-btn{transition:box-shadow .2s ease,transform .2s ease,filter .2s ease}
    .primary-btn,.btn-primary,.submit-btn,.follow-btn,.send-btn,button.primary{background:linear-gradient(135deg,#51baff,#247aff 55%,#174ee8)!important;color:#fff!important;border:1px solid #438dff!important;box-shadow:0 7px 22px #2679ff38,0 0 20px #368aff18!important;border-radius:14px!important}
    .primary-btn:hover,.btn-primary:hover,.submit-btn:hover,.follow-btn:hover,.send-btn:hover{box-shadow:0 9px 28px #2679ff52,0 0 24px #368aff28!important;filter:saturate(1.08)}
    .eyebrow{color:#176bff!important}
    .muted,.notification-time,.subtitle,.hint{color:#7183a0!important}
    .notification-row{border-bottom-color:#e5edfb!important}
    .notification-row.unread{background:linear-gradient(90deg,#eaf3ff,#f8fbff)!important;border-radius:14px}
    .avatar{box-shadow:0 0 0 3px #e9f2ff,0 5px 15px #2679ff1a}
    .bottom-nav,.nav-bar,.mobile-nav{background:rgba(255,255,255,.94)!important;border-top:1px solid #dce8fb!important;box-shadow:0 -8px 28px rgba(25,104,255,.07)!important;backdrop-filter:blur(18px)}
    .active,.nav-item.active,.tab.active{color:#176bff!important}
    .tab,.chip,.pill{border-color:#dce8fb!important}
    .tab.active,.chip.active,.pill.active{background:#e9f2ff!important;color:#155ce5!important;box-shadow:0 0 16px #287bff15}
    .modal,.modal-content,.dialog{background:#fff!important;color:#102344!important;border:1px solid #dce8fb!important;box-shadow:0 22px 70px #123d7b25,0 0 35px #368aff12!important;border-radius:24px!important}
    .boot-spinner{border-color:#dce8fb!important;border-top-color:#247aff!important}
    ::selection{background:#b9d6ff;color:#102344}
    @media(max-width:600px){.content{padding:15px 12px 24px}.topbar{padding:0 13px}.panel,.card,.post-card,.profile-card,.chat-card,.form-card,.section-card,.modal-card,.auth-card,.composer{border-radius:19px!important}}


    /* Keep navigation truly hidden while its hidden class is active during startup/loading. */
    .bottom-nav.hidden,.nav-bar.hidden,.mobile-nav.hidden{display:none!important;visibility:hidden!important;pointer-events:none!important}
    /* Premium floating blue-white glass bottom navigation */
    .bottom-nav{position:fixed!important;left:50%!important;bottom:calc(10px + env(safe-area-inset-bottom))!important;transform:translateX(-50%)!important;width:calc(100% - 28px)!important;max-width:760px!important;height:76px!important;padding:8px 12px!important;display:flex!important;justify-content:space-around!important;align-items:center!important;gap:3px!important;background:rgba(255,255,255,.78)!important;border:1px solid rgba(255,255,255,.96)!important;border-radius:28px!important;box-shadow:0 10px 34px rgba(34,104,205,.18),inset 0 1px 0 rgba(255,255,255,.95)!important;backdrop-filter:blur(24px) saturate(160%)!important;-webkit-backdrop-filter:blur(24px) saturate(160%)!important;z-index:100!important;overflow:visible!important}
    .nav-btn{position:relative!important;flex:1!important;min-width:0!important;height:58px!important;padding:5px 2px!important;display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:center!important;gap:3px!important;border:0!important;border-radius:17px!important;background:transparent!important;color:#8193ad!important;font-size:11px!important;font-weight:600!important;line-height:1.15!important;text-shadow:none!important;box-shadow:none!important}
    .nav-btn b{display:flex!important;align-items:center!important;justify-content:center!important;width:27px!important;height:27px!important;font-size:25px!important;line-height:1!important;font-weight:500!important;filter:none!important}
    .nav-btn.active{color:#176bff!important;background:rgba(36,123,255,.09)!important;text-shadow:none!important}
    .nav-btn.active b{filter:drop-shadow(0 2px 5px rgba(22,119,255,.22))!important}
    .nav-btn#createBtn{flex:1.08!important;overflow:visible!important;color:#7187a6!important}
    .nav-btn#createBtn b{box-sizing:border-box!important;flex:0 0 54px!important;width:54px!important;min-width:54px!important;height:54px!important;aspect-ratio:1/1!important;margin-top:-27px!important;margin-bottom:0!important;padding:0!important;display:flex!important;align-items:center!important;justify-content:center!important;border-radius:50%!important;background:linear-gradient(145deg,#7dcaff 0%,#287cff 60%,#155ce9 100%)!important;color:#fff!important;font-size:29px!important;font-weight:400!important;line-height:1!important;border:4px solid rgba(255,255,255,.96)!important;box-shadow:0 6px 18px rgba(30,112,255,.3),inset 0 1px 3px rgba(255,255,255,.8)!important}
    .nav-btn#createBtn{padding-top:20px!important}
    .nav-btn#createBtn.active{background:transparent!important;color:#176bff!important}
    body{padding-bottom:calc(108px + env(safe-area-inset-bottom))!important}
    @media(max-width:380px){.bottom-nav{width:calc(100% - 18px)!important;padding-left:7px!important;padding-right:7px!important}.nav-btn{font-size:10px!important}.nav-btn#createBtn b{flex-basis:49px!important;width:49px!important;min-width:49px!important;height:49px!important;font-size:27px!important}}

      /* Finger-following horizontal swipe between primary tabs; bottom nav stays fixed. */
    @media (max-width:760px){
      body.dot-swipe-active{overflow-x:hidden}
      .dot-swipe-dragging{will-change:transform;transition:none!important}
      .dot-swipe-preview{position:fixed!important;left:0!important;right:0!important;top:72px!important;bottom:calc(76px + env(safe-area-inset-bottom))!important;width:100%!important;max-width:760px!important;margin:0 auto!important;overflow-y:auto!important;z-index:15!important;background:var(--bg)!important;will-change:transform;box-shadow:0 0 30px rgba(20,80,160,.08)}
    }
\n

body.script:
//
(function(){
  'use strict';
  var firebaseConfig = {
    apiKey: "AIzaSyAev5VMUVrwUBJijiDN5-EAmkBzB9EH4L0",
    authDomain: "dot-tag-89e39.firebaseapp.com",
    projectId: "dot-tag-89e39",
    storageBucket: "dot-tag-89e39.firebasestorage.app",
    messagingSenderId: "579943607333",
    appId: "1:579943607333:web:486d6d3bb12656b7b723cc"
  };
  var configured = firebaseConfig.apiKey.indexOf('PASTE_') !== 0 &&
    firebaseConfig.projectId.indexOf('PASTE_') !== 0;
  var appAuth = null, store = null, currentUser = null;
  var isSignup = false, activeChatId = null, activeOtherUid = null;
  var activeOtherName = 'Conversation', unsubscribeChats = null, unsubscribeMessages = null;
  var followCountsUnsubs = [];
  var unsubscribeNotifications = null, notificationRows = [];
  var unsubscribePosts = null, pendingPostImage = '';
  var postLikeUnsubs = {}, likeActionBusy = {};
  var postPublishBusy = false;
  var profileCache = {};
  var followActionBusy = false;
  var $ = function(id){return document.getElementById(id);};
  var views = ['authView','homeView','createPostView','chatsView','chatRoomView','exploreView','reelsView','profileView','publicProfileView','notificationsView'];
  function showStatus(id,msg){$(id).textContent=msg||'';}
  function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function initials(s){s=String(s||'d.').trim();return esc(s.charAt(0).toUpperCase()||'d.');}
  function showView(id){
    $('bootScreen').classList.add('hidden');
    views.forEach(function(v){$(v).classList.toggle('hidden',v!==id);});
    $('mainTopbar').classList.toggle('hidden',id==='authView'||id==='chatRoomView');
    $('bottomNav').classList.toggle('hidden',!currentUser||id==='chatRoomView');
    document.querySelectorAll('.nav-btn[data-view]').forEach(function(b){b.classList.toggle('active',b.getAttribute('data-view')===id);});
    window.scrollTo(0,0);
  }
  function profilePath(uid){return store.collection('profiles').doc(uid);}
  function followPath(followerId,followingId){return store.collection('follows').doc(followerId+'_'+followingId);}
  function loadFollowCounts(uid){
    if(!store||!uid)return;
    followCountsUnsubs.forEach(function(u){try{u();}catch(e){}});followCountsUnsubs=[];
    followCountsUnsubs.push(store.collection('follows').where('followingId','==',uid).onSnapshot(function(s){$('statFollowers').textContent=String(s.size);},function(e){console.warn('Followers count unavailable',e);$('statFollowers').textContent='—';}));
    followCountsUnsubs.push(store.collection('follows').where('followerId','==',uid).onSnapshot(function(s){$('statFollowing').textContent=String(s.size);},function(e){console.warn('Following count unavailable',e);$('statFollowing').textContent='—';}));
  }
  function loadFollowList(kind,targetUid,isPublic){
    if(!currentUser||!store)return;
    var uid=targetUid||currentUser.uid,field=kind==='followers'?'followingId':'followerId';
    var card=$(isPublic?'publicFollowListCard':'followListCard'),title=$(isPublic?'publicFollowListTitle':'followListTitle'),box=$(isPublic?'publicFollowListContent':'followListContent');
    card.classList.remove('hidden');title.textContent=kind==='followers'?'Followers':'Following';box.textContent='Loading…';
    store.collection('follows').where(field,'==',uid).limit(100).get().then(function(snap){
      box.innerHTML='';
      if(snap.empty){box.innerHTML='<div class="empty">No '+kind+' yet.</div>';return;}
      var entries=snap.docs.map(function(doc){var f=doc.data();return {uid:kind==='followers'?f.followerId:f.followingId};}).filter(function(x){return x.uid&&x.uid!==uid;});
      return Promise.all(entries.map(function(x){return profilePath(x.uid).get().then(function(d){return {uid:x.uid,p:d.exists?d.data():{}};});})).then(function(rows){
        box.innerHTML='';
        rows.forEach(function(row){
          var p=row.p,n=p.displayName||p.username||'dot.tag user',handle=p.username||'user',r=document.createElement('div');r.className='follow-list-row';
          var avatar=p.profileImage?'<img alt="Profile photo" src="'+esc(p.profileImage)+'" />':initials(n);
          r.innerHTML='<div class="avatar">'+avatar+'</div><div class="grow"><strong class="truncate">'+esc(n)+'</strong><div class="muted small truncate">@'+esc(handle)+'</div></div><div class="follow-list-actions"><button class="secondary" type="button">View</button></div>';
          r.querySelector('.grow').addEventListener('click',function(){card.classList.add('hidden');openPublicProfile(row.uid,isPublic?'publicProfileView':'profileView');});
          r.querySelector('.avatar').style.cursor='pointer';r.querySelector('.avatar').addEventListener('click',function(){card.classList.add('hidden');openPublicProfile(row.uid,isPublic?'publicProfileView':'profileView');});
          r.querySelector('.follow-list-actions button').addEventListener('click',function(){card.classList.add('hidden');openPublicProfile(row.uid,isPublic?'publicProfileView':'profileView');});
          box.appendChild(r);
        });
        if(!rows.length)box.innerHTML='<div class="empty">No '+kind+' to show.</div>';
      });
    }).catch(function(e){console.error('Follow list failed',e);box.textContent='Could not load list. Check Firestore rules: '+e.message;});
  }
  function notificationPath(){return store.collection('notifications');}
  function notificationTime(ts){try{if(!ts)return 'Just now';var d=ts.toDate?ts.toDate():new Date(ts);return d.toLocaleString();}catch(e){return 'Recent';}}
  function updateNotificationBadge(rows){
    var unread=(rows||[]).filter(function(n){return n.read!==true;}).length, badge=$('notifyBadge');
    badge.textContent=unread>99?'99+':String(unread);badge.classList.toggle('hidden',unread===0);
    $('notifyBtn').setAttribute('aria-label',unread?('Notifications, '+unread+' unread'):'Notifications');
  }
  function notificationActorProfile(uid){return profilePath(uid).get().then(function(d){return d.exists?d.data():{};}).catch(function(){return {};});}
  function renderNotifications(rows){
    var box=$('notificationList');box.innerHTML='';
    if(!rows.length){box.innerHTML='<div class="empty"><div class="big">🔔</div><strong>No notifications yet</strong><p>Follow and message activity will appear here.</p></div>';return;}
    rows.forEach(function(n){
      var row=document.createElement('div');row.className='notification-row'+(n.read===true?'':' unread');
      var name=n.actorName||'dot.tag user', avatar=n.actorPhoto?'<img alt="Profile photo" src="'+esc(n.actorPhoto)+'" />':initials(name);
      var copy=n.type==='follow'?'started following you':(n.type==='message'?'sent you a message':'interacted with you');
      row.innerHTML='<div class="avatar">'+avatar+'</div><div class="notification-copy"><strong>'+esc(name)+'</strong> '+copy+'<div class="notification-time">'+esc(notificationTime(n.createdAt))+'</div></div>'+(n.read===true?'':'<span class="notification-dot" aria-label="Unread"></span>');
      row.addEventListener('click',function(){
        var ref=notificationPath().doc(n.id);
        var mark=n.read===true?Promise.resolve():ref.update({read:true});
        mark.catch(function(e){console.warn('Could not mark notification read',e);}).then(function(){
          n.read=true;row.classList.remove('unread');var dot=row.querySelector('.notification-dot');if(dot)dot.remove();updateNotificationBadge(notificationRows);
          if(n.type==='message'&&n.chatId&&n.actorId){openChat(n.chatId,n.actorId,n.actorName||'Conversation');}
          else if(n.actorId){showView('notificationsView');openPublicProfile(n.actorId,'notificationsView');}
        });
      });
      box.appendChild(row);
    });
  }
  function listenNotifications(){
    if(unsubscribeNotifications){unsubscribeNotifications();unsubscribeNotifications=null;}
    if(!store||!currentUser)return;
    unsubscribeNotifications=notificationPath().where('recipientId','==',currentUser.uid).limit(100).onSnapshot(function(snap){
      notificationRows=snap.docs.map(function(d){var n=d.data();n.id=d.id;return n;}).sort(function(a,b){var at=a.createdAt&&a.createdAt.toMillis?a.createdAt.toMillis():0,bt=b.createdAt&&b.createdAt.toMillis?b.createdAt.toMillis():0;return bt-at;});
      updateNotificationBadge(notificationRows);
      if(!$('notificationsView').classList.contains('hidden'))renderNotifications(notificationRows);
    },function(e){console.error('Notifications unavailable',e);showStatus('notificationStatus','Could not load notifications. Check Firestore rules for /notifications.');});
  }
  function createNotification(data){
    if(!store||!data||!data.recipientId||!data.actorId||data.recipientId===data.actorId)return Promise.resolve();
    return notificationActorProfile(data.actorId).then(function(p){
      var payload={recipientId:data.recipientId,actorId:data.actorId,actorName:p.displayName||p.username||currentUser.displayName||'dot.tag user',actorPhoto:p.profileImage||'',type:data.type,read:false,createdAt:firebase.firestore.FieldValue.serverTimestamp()};
      if(data.chatId)payload.chatId=data.chatId;if(data.messageId)payload.messageId=data.messageId;
      return notificationPath().add(payload);
    });
  }
  function markAllNotificationsRead(){
    if(!currentUser||!store)return;
    var unread=notificationRows.filter(function(n){return n.read!==true;});
    if(!unread.length){showStatus('notificationStatus','All caught up.');return;}
    var batches=[];for(var i=0;i<unread.length;i+=400){var b=store.batch();unread.slice(i,i+400).forEach(function(n){b.update(notificationPath().doc(n.id),{read:true});});batches.push(b.commit());}
    Promise.all(batches).then(function(){showStatus('notificationStatus','All notifications marked as read.');}).catch(function(e){showStatus('notificationStatus','Could not mark all read: '+e.message);});
  }

  function renderFollowButton(targetUid,container,initiallyFollowing){
    if(!container||!currentUser||targetUid===currentUser.uid)return;
    var btn=container.querySelector('[data-follow-button]');if(!btn)return;
    btn.disabled=true;btn.textContent='Checking…';
    followPath(currentUser.uid,targetUid).get().then(function(doc){
      var following=doc.exists;btn.disabled=false;btn.textContent=following?'Following':'Follow';btn.classList.toggle('following',following);btn.setAttribute('aria-pressed',following?'true':'false');
      btn.onclick=function(){if(followActionBusy||!currentUser)return;followActionBusy=true;btn.disabled=true;var ref=followPath(currentUser.uid,targetUid);
        var task=following?ref.delete():ref.set({followerId:currentUser.uid,followingId:targetUid,createdAt:firebase.firestore.FieldValue.serverTimestamp()});
        task.then(function(){following=!following;btn.textContent=following?'Following':'Follow';btn.classList.toggle('following',following);btn.setAttribute('aria-pressed',following?'true':'false');if(currentUser)loadFollowCounts(currentUser.uid);if(following)return createNotification({recipientId:targetUid,actorId:currentUser.uid,type:'follow'}).catch(function(e){console.warn('Follow notification could not be created',e);});})
        .catch(function(e){console.error('Follow action failed',e);alert('Follow update failed: '+e.message+' Check Firestore rules for the follows collection.');})
        .then(function(){btn.disabled=false;followActionBusy=false;});
      };
    }).catch(function(e){btn.disabled=true;btn.textContent='Unavailable';console.warn('Follow state unavailable',e);});
  }
  function setProfile(user,profile){
    var name=(profile&&profile.displayName)||user.displayName||'dot.tag user';
    var handle=(profile&&profile.username)||'user';
    $('helloName').textContent=name;
    $('profileName').textContent=name;
    $('profileHandle').textContent='@'+handle;
    $('profileEmail').textContent=user.email||'';
    var avatar=$('profileAvatar');
    var photo=(profile&&profile.profileImage)||'';
    if(photo){avatar.innerHTML='<img alt="Profile photo" src="'+photo+'" />';}else{avatar.textContent=initials(name);}
    $('profileBio').textContent=(profile&&profile.bio)||'Add a short bio about yourself.';
    if(user&&user.uid===currentUser.uid)loadFollowCounts(user.uid);
    if($('editDisplayName'))$('editDisplayName').value=name;
    if($('editBio'))$('editBio').value=(profile&&profile.bio)||'';
  }
  var publicProfileUid=null, publicProfileBackView='exploreView';
  function openPublicProfile(uid,backView){
    if(!currentUser||!uid)return;
    if(uid===currentUser.uid){showView('profileView');return;}
    publicProfileUid=uid;publicProfileBackView=backView||'exploreView';
    $('publicFollowListCard').classList.add('hidden');$('publicName').textContent='Loading profile…';$('publicHandle').textContent='';$('publicBio').textContent='';
    $('publicProfileStatus').textContent='Loading…';$('publicAvatar').textContent='d.';
    $('publicFollowBtn').disabled=true;$('publicMessageBtn').disabled=true;
    showView('publicProfileView');
    profilePath(uid).get().then(function(doc){
      if(!doc.exists){$('publicName').textContent='Profile not found';$('publicProfileStatus').textContent='This profile may have been removed.';return;}
      var p=doc.data(),name=p.displayName||p.username||'dot.tag user';
      $('publicName').textContent=name;$('publicHandle').textContent='@'+(p.username||'user');
      $('publicBio').textContent=p.bio||'No bio yet.';
      if(p.profileImage){$('publicAvatar').innerHTML='<img alt="Profile photo" src="'+esc(p.profileImage)+'" />';}
      else{$('publicAvatar').textContent=initials(name);}
      $('publicProfileStatus').textContent='';
      $('publicFollowBtn').disabled=false;$('publicMessageBtn').disabled=false;
      renderFollowButton(uid,$('publicProfileView'),false);
      Promise.all([
        store.collection('follows').where('followingId','==',uid).get(),
        store.collection('follows').where('followerId','==',uid).get()
      ]).then(function(counts){
        $('publicFollowers').textContent=String(counts[0].size);
        $('publicFollowing').textContent=String(counts[1].size);
      }).catch(function(e){console.warn('Public profile counts unavailable',e);});
      postPath().where('authorId','==',uid).limit(100).get().then(function(posts){$('publicPosts').textContent=String(posts.size);}).catch(function(){ $('publicPosts').textContent='0'; });
      $('publicMessageBtn').onclick=function(){
        if(!currentUser||!publicProfileUid)return;
        var target=publicProfileUid,ids=[currentUser.uid,target].sort(),chatId=ids.join('_'),ref=store.collection('chats').doc(chatId);
        ref.get().then(function(d){return d.exists?null:ref.set({participants:ids,createdAt:firebase.firestore.FieldValue.serverTimestamp(),updatedAt:firebase.firestore.FieldValue.serverTimestamp(),lastMessage:'',lastSenderId:''});})
        .then(function(){openChat(chatId,target,name);}).catch(function(e){alert('Could not open chat: '+e.message);});
      };
    }).catch(function(e){$('publicName').textContent='Could not load profile';$('publicProfileStatus').textContent=e.message||'Please try again.';});
  }
  function postPath(){return store.collection('posts');}
  function formatPostTime(ts){try{if(!ts)return 'Just now';var d=ts.toDate?ts.toDate():new Date(ts);return d.toLocaleString();}catch(e){return 'Recently';}}
  function openCreatePost(){if(!currentUser){showView('authView');return;}pendingPostImage='';$('postText').value='';$('postImageInput').value='';$('postImagePreview').src='';$('postImagePreview').classList.add('hidden');$('removePostImage').classList.add('hidden');showStatus('postCreateStatus','');showView('createPostView');}
  function listenPosts(){
    if(unsubscribePosts){unsubscribePosts();unsubscribePosts=null;}
    clearPostLikeListeners();
    if(!store||!currentUser)return;
    showStatus('feedStatus','Loading posts…');
    unsubscribePosts=postPath().orderBy('createdAt','desc').limit(50).onSnapshot(function(snap){
      var box=$('postFeed');box.innerHTML='';
      if(snap.empty){box.innerHTML='<div class="empty"><div class="big">🌱</div><strong>No posts yet</strong><p>Be the first to share something with dot.tag.</p></div>';showStatus('feedStatus','');$('statPosts').textContent='0';return;}
      snap.docs.forEach(function(doc){
        var d=doc.data()||{},name=d.authorName||'dot.tag user',handle=d.authorUsername||'user';
        var avatar=d.authorPhoto?'<img alt="Profile photo" src="'+esc(d.authorPhoto)+'" />':initials(name);
        var el=document.createElement('article');el.className='feed-post';
        var head='<div class="post-meta"><div class="avatar">'+avatar+'</div><div class="grow"><strong>'+esc(name)+'</strong><div class="muted small">@'+esc(handle)+'</div><div class="post-time">'+esc(formatPostTime(d.createdAt))+'</div></div>'+(d.authorId===currentUser.uid?'<span class="pill">YOU</span>':'')+'</div>';
        var image=d.imageData?'<img class="post-image" alt="Post photo" loading="lazy" src="'+esc(d.imageData)+'"/>':'';
        var copy=d.text?'<div class="post-text">'+esc(d.text)+'</div>':'';
        var actions='<div class="post-actions"><button type="button" class="like-btn" id="like-'+esc(doc.id)+'" data-post-id="'+esc(doc.id)+'"><span class="heart">♡</span><span class="like-label">Like</span><span class="like-count">0</span></button></div>';
        el.innerHTML=head+image+copy+actions;
        box.appendChild(el);
        watchPostLikes(doc.id,el);
        el.querySelector('.like-btn').addEventListener('click',function(){togglePostLike(doc.id,el);});
      });
      showStatus('feedStatus','');
      postPath().where('authorId','==',currentUser.uid).limit(100).get().then(function(own){$('statPosts').textContent=String(own.size);}).catch(function(){ });
    },function(e){console.error('Feed unavailable',e);showStatus('feedStatus','Could not load posts: '+(e.message||'Check Firestore rules for /posts.'));$('postFeed').innerHTML='<div class="empty">Posts could not be loaded. Check Firestore rules.</div>';});
  }
  function postLikesPath(postId){return postPath().doc(postId).collection('likes');}
  function watchPostLikes(postId,el){
    if(postLikeUnsubs[postId]){postLikeUnsubs[postId]();delete postLikeUnsubs[postId];}
    postLikeUnsubs[postId]=postLikesPath(postId).onSnapshot(function(snap){
      if(!el||!el.isConnected)return;
      var btn=el.querySelector('.like-btn');if(!btn)return;
      var liked=snap.docs.some(function(d){return d.id===currentUser.uid;});
      btn.classList.toggle('liked',liked);
      btn.querySelector('.heart').textContent=liked?'♥':'♡';
      btn.querySelector('.like-label').textContent=liked?'Liked':'Like';
      btn.querySelector('.like-count').textContent=String(snap.size);
      btn.setAttribute('aria-pressed',liked?'true':'false');
    },function(e){console.error('Likes unavailable',e);var btn=el&&el.querySelector('.like-btn');if(btn)btn.title='Likes unavailable: check Firestore rules';});
  }
  function togglePostLike(postId,el){
    if(!currentUser||!store){showView('authView');return;}
    if(likeActionBusy[postId])return;
    likeActionBusy[postId]=true;
    var btn=el.querySelector('.like-btn');if(btn)btn.disabled=true;
    var ref=postLikesPath(postId).doc(currentUser.uid);
    ref.get().then(function(doc){
      if(doc.exists)return ref.delete();
      return ref.set({userId:currentUser.uid,createdAt:firebase.firestore.FieldValue.serverTimestamp()});
    }).catch(function(e){console.error('Like action failed',e);alert('Like update failed: '+(e.message||'Check Firestore rules for /posts/{postId}/likes.'));})
    .then(function(){likeActionBusy[postId]=false;if(btn&&btn.isConnected)btn.disabled=false;},function(){likeActionBusy[postId]=false;if(btn&&btn.isConnected)btn.disabled=false;});
  }
  function clearPostLikeListeners(){Object.keys(postLikeUnsubs).forEach(function(id){try{postLikeUnsubs[id]();}catch(e){}});postLikeUnsubs={};}

  function publishPost(){
    if(!currentUser||!store||postPublishBusy)return;
    var text=$('postText').value.trim();
    if(!text&&!pendingPostImage){showStatus('postCreateStatus','Write something or add a photo first.');return;}
    if(text.length>1800){showStatus('postCreateStatus','Post text must be 1,800 characters or fewer.');return;}
    postPublishBusy=true;$('publishPost').disabled=true;showStatus('postCreateStatus','Publishing…');
    profilePath(currentUser.uid).get().then(function(doc){
      var p=doc.exists?doc.data():{},data={authorId:currentUser.uid,authorName:p.displayName||currentUser.displayName||'dot.tag user',authorUsername:p.username||'user',text:text,createdAt:firebase.firestore.FieldValue.serverTimestamp()};
      if(p.profileImage)data.authorPhoto=p.profileImage;if(pendingPostImage)data.imageData=pendingPostImage;
      return postPath().add(data);
    }).then(function(){pendingPostImage='';$('postText').value='';$('postImageInput').value='';$('postImagePreview').src='';$('postImagePreview').classList.add('hidden');$('removePostImage').classList.add('hidden');showView('homeView');showStatus('feedStatus','Post published!');})
    .catch(function(e){console.error('Post publish failed',e);showStatus('postCreateStatus','Could not publish: '+(e.message||'Check Firestore rules for /posts.'));})
    .then(function(){postPublishBusy=false;$('publishPost').disabled=false;});
  }
  function bootFirebase(){
    if(!configured){showStatus('authStatus','Firebase not configured yet. Add your Firebase web app config in the theme XML.');return false;}
    if(!window.firebase){showStatus('authStatus','Firebase scripts did not load. Check your internet connection.');return false;}
    if(!firebase.apps.length)firebase.initializeApp(firebaseConfig);
    appAuth=firebase.auth();store=firebase.firestore();return true;
  }
  function startApp(user){
    currentUser=user;
    profilePath(user.uid).get().then(function(doc){
      var profile=doc.exists?doc.data():{};
      if(!doc.exists){
        return profilePath(user.uid).set({
          displayName:user.displayName||'dot.tag user',
          username:'user_'+user.uid.substring(0,8).toLowerCase(),
          createdAt:firebase.firestore.FieldValue.serverTimestamp()
        }).then(function(){setProfile(user,{displayName:user.displayName||'dot.tag user',username:'user_'+user.uid.substring(0,8).toLowerCase()});});
      }
      setProfile(user,profile);
    }).catch(function(e){console.error(e);setProfile(user,{});});
    showView('homeView');listenChats();listenPosts();loadFollowCounts(user.uid);listenNotifications(); 
  }
  function stopListeners(){
    followCountsUnsubs.forEach(function(u){try{u();}catch(e){}});followCountsUnsubs=[];
    if(unsubscribeChats){unsubscribeChats();unsubscribeChats=null;}
    if(unsubscribeMessages){unsubscribeMessages();unsubscribeMessages=null;}
    if(unsubscribeNotifications){unsubscribeNotifications();unsubscribeNotifications=null;}
    if(unsubscribePosts){unsubscribePosts();unsubscribePosts=null;}
    notificationRows=[];updateNotificationBadge([]);
  }
  function signOut(){stopListeners();activeChatId=null;activeOtherUid=null;currentUser=null;appAuth.signOut();}
  $('switchAuth').addEventListener('click',function(){
    isSignup=!isSignup;$('signupFields').classList.toggle('hidden',!isSignup);
    $('authTitle').textContent=isSignup?'Create your account':'Welcome back';
    $('authSubtitle').textContent=isSignup?'Join dot.tag and meet your people.':'Log in to continue to your conversations.';
    $('authSubmit').textContent=isSignup?'Create account':'Log in';
    $('switchText').textContent=isSignup?'Already have an account?':'New to dot.tag?';
    $('switchAuth').textContent=isSignup?'Log in':'Create account';
    $('password').setAttribute('autocomplete',isSignup?'new-password':'current-password');
    showStatus('authStatus','');
  });
  $('authSubmit').addEventListener('click',function(){
    if(!bootFirebase())return;
    var email=$('email').value.trim().toLowerCase(), pass=$('password').value;
    if(!email||!pass){showStatus('authStatus','Enter your email and password.');return;}
    if(pass.length<6){showStatus('authStatus','Password must be at least 6 characters.');return;}
    var button=$('authSubmit');button.disabled=true;showStatus('authStatus','Please wait…');
    var task;
    if(isSignup){
      var name=$('displayName').value.trim(), username=$('username').value.trim().toLowerCase();
      if(!name||name.length>40||! /^[a-z0-9_]{3,20}$/.test(username)){
        button.disabled=false;showStatus('authStatus','Enter a display name (max 40) and username (3–20 letters, numbers or _).');return;
      }
      task=appAuth.createUserWithEmailAndPassword(email,pass).then(function(cred){
        return cred.user.updateProfile({displayName:name}).then(function(){
          return profilePath(cred.user.uid).set({
            displayName:name,username:username,
            createdAt:firebase.firestore.FieldValue.serverTimestamp()
          });
        });
      });
    }else{task=appAuth.signInWithEmailAndPassword(email,pass);}
    task.then(function(){showStatus('authStatus','');}).catch(function(e){
      showStatus('authStatus',e.message||'Could not sign in.');button.disabled=false;
    });
  });
  function listenChats(){
    if(unsubscribeChats)unsubscribeChats();
    if(!store||!currentUser)return;
    unsubscribeChats=store.collection('chats').where('participants','array-contains',currentUser.uid)
      .onSnapshot(function(snapshot){
        var list=$('chatList');var search=($('chatSearch').value||'').toLowerCase();
        var docs=snapshot.docs.slice().sort(function(a,b){
          var at=a.data().updatedAt&&a.data().updatedAt.toMillis?a.data().updatedAt.toMillis():0;
          var bt=b.data().updatedAt&&b.data().updatedAt.toMillis?b.data().updatedAt.toMillis():0;return bt-at;
        });
        list.innerHTML='';
        var visible=0;
        docs.forEach(function(doc){
          var d=doc.data(), other=(d.participants||[]).filter(function(uid){return uid!==currentUser.uid;})[0];
          if(!other)return;
          profilePath(other).get().then(function(pdoc){
            if(!pdoc.exists)return;
            var p=pdoc.data(), name=p.displayName||p.username||'dot.tag user';
            profileCache[other]={name:name,username:p.username||''};
            if(search && name.toLowerCase().indexOf(search)<0 && String(p.username||'').toLowerCase().indexOf(search)<0)return;
            var row=document.createElement('div');row.className='chat-row';
            row.innerHTML='<div class="avatar">'+initials(name)+'</div><div class="grow"><div class="chat-name truncate">'+esc(name)+'</div><div class="chat-preview truncate">'+esc(d.lastMessage||'Start a conversation')+'</div></div><span class="muted small">›</span>';
            row.addEventListener('click',function(){openChat(doc.id,other,name);});
            list.appendChild(row);visible++;
            var empty=list.querySelector('.empty');if(empty)empty.remove();
          }).catch(function(e){console.warn('Profile lookup failed',e);});
        });
        if(!docs.length){list.innerHTML='<div class="empty"><div class="big">💬</div><strong>No chats yet</strong><p>Tap + to find someone by username.</p></div>';}
        else if(search && !docs.length){list.innerHTML='<div class="empty">No conversations found.</div>';}
      },function(error){console.error(error);$('chatList').innerHTML='<div class="empty">Could not load chats. Check Firestore rules and indexes.</div>';});
  }
  $('chatSearch').addEventListener('input',function(){listenChats();});
  function startChat(){
    if(!currentUser)return;
    var username=window.prompt('Enter their exact username (without @):');
    if(!username)return;username=username.trim().toLowerCase();
    if(!/^[a-z0-9_]{3,20}$/.test(username)){alert('Username must be 3–20 letters, numbers or underscores.');return;}
    store.collection('profiles').where('username','==',username).limit(2).get().then(function(snap){
      if(snap.empty){alert('Username not found.');return;}
      if(snap.size>1){alert('This username is duplicated. Username claiming must be secured before public launch.');return;}
      var otherDoc=snap.docs[0], other=otherDoc.id, p=otherDoc.data();
      if(other===currentUser.uid){alert('You cannot start a chat with yourself.');return;}
      var ids=[currentUser.uid,other].sort(), chatId=ids.join('_'), ref=store.collection('chats').doc(chatId);
      return ref.get().then(function(doc){
        if(doc.exists)return;
        return ref.set({participants:ids,createdAt:firebase.firestore.FieldValue.serverTimestamp(),
          updatedAt:firebase.firestore.FieldValue.serverTimestamp(),lastMessage:'',lastSenderId:''});
      }).then(function(){openChat(chatId,other,p.displayName||p.username||'Conversation');});
    }).catch(function(e){alert('Could not start chat: '+e.message);});
  }
  $('newChatBtn').addEventListener('click',startChat);
  function openChat(chatId,otherUid,name){
    activeChatId=chatId;activeOtherUid=otherUid;activeOtherName=name;
    $('roomName').textContent=name;$('roomAvatar').textContent=initials(name);$('messages').innerHTML='';
    showView('chatRoomView');
    if(unsubscribeMessages)unsubscribeMessages();
    unsubscribeMessages=store.collection('chats').doc(chatId).collection('messages')
      .orderBy('createdAt','desc').limit(100).onSnapshot(function(snap){
        var box=$('messages');box.innerHTML='';
        if(snap.empty){box.innerHTML='<div class="empty">Say hello 👋</div>';return;}
        snap.docs.forEach(function(doc){
          var d=doc.data(), mine=d.senderId===currentUser.uid;
          var el=document.createElement('div');el.className='bubble'+(mine?' mine':'');
          el.textContent=d.text||'';
          box.appendChild(el);
        });
      },function(e){console.error(e);$('messages').innerHTML='<div class="empty">Messages unavailable. Check Firestore rules.</div>';});
  }
  $('backToChats').addEventListener('click',function(){showView('chatsView');});
  $('messageForm').addEventListener('submit',function(e){
    e.preventDefault();if(!currentUser||!activeChatId)return;
    var input=$('messageInput'),text=input.value.trim();if(!text)return;
    if(text.length>2000){alert('Messages must be 2,000 characters or fewer.');return;}
    input.value='';
    var chat=store.collection('chats').doc(activeChatId), msg=chat.collection('messages').doc();
    var batch=store.batch();
    batch.set(msg,{senderId:currentUser.uid,text:text,createdAt:firebase.firestore.FieldValue.serverTimestamp()});
    batch.update(chat,{lastMessage:text,lastSenderId:currentUser.uid,updatedAt:firebase.firestore.FieldValue.serverTimestamp()});
    batch.commit().then(function(){return createNotification({recipientId:activeOtherUid,actorId:currentUser.uid,type:'message',chatId:activeChatId,messageId:msg.id});}).catch(function(e){console.error(e);alert('Message was sent, but notification may not have been saved: '+e.message);});
  });
  document.querySelectorAll('.nav-btn[data-view]').forEach(function(b){b.addEventListener('click',function(){showView(b.getAttribute('data-view'));});});
  $('createBtn').addEventListener('click',openCreatePost);

  $('cancelCreatePost').addEventListener('click',function(){showView('homeView');});
