    if(file.size>10*1024*1024){showStatus('postCreateStatus','Choose a photo smaller than 10 MB.');this.value='';return;}
    showStatus('postCreateStatus','Compressing photo…');var reader=new FileReader();
    reader.onerror=function(){showStatus('postCreateStatus','Could not read that photo.');};
    reader.onload=function(ev){var img=new Image();img.onerror=function(){showStatus('postCreateStatus','Could not open that photo. Try JPG or PNG.');};
      img.onload=function(){var max=900,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));var ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);var quality=.72,data='';do{data=canvas.toDataURL('image/jpeg',quality);quality-=.08;}while(data.length>190000&&quality>.24);if(data.length>200000){showStatus('postCreateStatus','Photo is too large after compression. Choose a smaller photo.');return;}pendingPostImage=data;$('postImagePreview').src=data;$('postImagePreview').classList.remove('hidden');$('removePostImage').classList.remove('hidden');showStatus('postCreateStatus','Photo ready. Publish when you are ready.');};img.src=ev.target.result;};reader.readAsDataURL(file);
  });
  $('removePostImage').addEventListener('click',function(){pendingPostImage='';$('postImageInput').value='';$('postImagePreview').src='';$('postImagePreview').classList.add('hidden');this.classList.add('hidden');showStatus('postCreateStatus','Photo removed.');});
