  $('refreshProfile').addEventListener('click',function(){
    if(!currentUser)return;
    showStatus('profileStatus','Refreshing…');
    profilePath(currentUser.uid).get().then(function(d){setProfile(currentUser,d.exists?d.data():{});showStatus('profileStatus','Profile refreshed.');}).catch(function(e){showStatus('profileStatus','Could not refresh profile: '+e.message);});
  });
  var pendingProfileImage=null;
  $('profilePhotoInput').addEventListener('change',function(){
    var file=this.files&&this.files[0];if(!file)return;
    if(!file.type||file.type.indexOf('image/')!==0){showStatus('profileStatus','Please choose an image file.');this.value='';return;}
    if(file.size>8*1024*1024){showStatus('profileStatus','Choose an image smaller than 8 MB.');this.value='';return;}
    showStatus('profileStatus','Preparing photo…');
    var reader=new FileReader();
    reader.onerror=function(){showStatus('profileStatus','Could not read this image. Try another photo.');};
    reader.onload=function(ev){
      var img=new Image();
      img.onerror=function(){showStatus('profileStatus','This image could not be opened. Try JPG or PNG.');};
      img.onload=function(){
        var max=256,scale=Math.min(1,max/Math.max(img.width,img.height));
        var canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));
        var ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);
        var quality=0.72,data='';
        do{data=canvas.toDataURL('image/jpeg',quality);quality-=0.1;}while(data.length>135000&&quality>0.32);
        if(data.length>150000){showStatus('profileStatus','Photo is still too large. Please choose a smaller image.');return;}
        pendingProfileImage=data;$('profileAvatar').innerHTML='<img alt="Profile photo preview" src="'+data+'" />';showStatus('profileStatus','Photo ready. Tap Save profile to keep it.');
      };img.src=ev.target.result;
    };reader.readAsDataURL(file);
  });
  $('removeProfilePhoto').addEventListener('click',function(){pendingProfileImage='';if(currentUser){var n=$('editDisplayName').value.trim()||'dot.tag user';$('profileAvatar').textContent=initials(n);}showStatus('profileStatus','Photo removal selected. Tap Save profile to confirm.');});
  $('saveProfile').addEventListener('click',function(){
