  /* Real drag-follow swipe. Only the four primary tabs participate. */
  (function(){
    var order=['homeView','chatsView','profileView'];
    var startX=0,startY=0,deltaX=0,active=null,preview=null,tracking=false;
    var threshold=64;
    function indexOfView(id){return order.indexOf(id);}
    function cleanup(){
      if(active){active.classList.remove('dot-swipe-dragging');active.style.transform='';active.style.transition='';}
      if(preview){preview.classList.remove('dot-swipe-preview');preview.style.transform='';preview.style.transition='';preview.classList.add('hidden');}
      document.body.classList.remove('dot-swipe-active');
      active=null;preview=null;tracking=false;deltaX=0;
    }
    document.addEventListener('touchstart',function(e){
      if(!e.touches||e.touches.length!==1||!currentUser)return;
      var target=e.target;
      if(target.closest('input,textarea,select,button,a,[contenteditable="true"],.story-strip,.messages,.composer'))return;
      var visible=order.filter(function(id){return !$(id).classList.contains('hidden');});
      if(visible.length!==1)return;
      startX=e.touches[0].clientX;startY=e.touches[0].clientY;deltaX=0;
      active=$(visible[0]);tracking=true;preview=null;
    },{passive:true});
    document.addEventListener('touchmove',function(e){
      if(!tracking||!active||!e.touches||e.touches.length!==1)return;
      var dx=e.touches[0].clientX-startX,dy=e.touches[0].clientY-startY;
      if(Math.abs(dx)<8&&Math.abs(dy)<8)return;
      if(Math.abs(dy)>Math.abs(dx)*1.15){tracking=false;return;}
      if(Math.abs(dx)<=Math.abs(dy)*1.15)return;
      var i=indexOfView(active.id),nextIndex=i+(dx<0?1:-1);
      if(i<0||nextIndex<0||nextIndex>=order.length){deltaX=dx*.22;active.style.transform='translateX('+deltaX+'px)';return;}
      if(!preview){
        preview=$(order[nextIndex]);preview.classList.remove('hidden');preview.classList.add('dot-swipe-preview');
        preview.style.transform='translateX('+(dx<0?window.innerWidth:-window.innerWidth)+'px)';
        preview.style.transition='none';active.classList.add('dot-swipe-dragging');
        document.body.classList.add('dot-swipe-active');
      }
      deltaX=dx;
      active.style.transform='translateX('+dx+'px)';
      preview.style.transform='translateX('+(dx+(dx<0?window.innerWidth:-window.innerWidth))+'px)';
    },{passive:true});
    document.addEventListener('touchend',function(){
      if(!tracking){cleanup();return;}
      if(!active){cleanup();return;}
      var i=indexOfView(active.id),nextIndex=i+(deltaX<0?1:-1);
      if(preview&&Math.abs(deltaX)>threshold&&nextIndex>=0&&nextIndex<order.length){
        var direction=deltaX<0?-1:1;
        active.style.transition='transform .2s ease-out';
        preview.style.transition='transform .2s ease-out';
        active.style.transform='translateX('+(direction*-window.innerWidth)+'px)';
        preview.style.transform='translateX(0px)';
        var destination=order[nextIndex];
        window.setTimeout(function(){cleanup();showView(destination);},205);
      }else{
        if(active)active.style.transition='transform .18s ease-out';
        if(active)active.style.transform='translateX(0px)';
        if(preview){preview.style.transition='transform .18s ease-out';preview.style.transform='translateX('+(deltaX<0?window.innerWidth:-window.innerWidth)+'px)';}
        window.setTimeout(cleanup,190);
      }
    },{passive:true});
    document.addEventListener('touchcancel',cleanup,{passive:true});
  })();


  if(bootFirebase()){
    appAuth.onAuthStateChanged(function(user){
      if(user){startApp(user);}else{stopListeners();currentUser=null;showView('authView');}
    },function(error){
      console.error('Auth state check failed',error);
      showView('authView');
      showStatus('authStatus','Could not check your session. Please log in again.');
    });
  }else{showView('authView');}
})();
